css:
.doc-page.cv{font-family:'Roboto','Noto Serif Bengali','Hind Siliguri',sans-serif}
.doc-page .en-cv{display:flex;min-height:295mm}
.doc-page .en-sidebar{width:33%;background:#eef2f5;padding:35px 25px;border-right:1px solid #dce4ec;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.doc-page .en-main{width:67%;padding:35px;background:#fff}
.doc-page .en-photo-box{width:120px;height:140px;background:#ddd;border:3px solid #fff;box-shadow:0 4px 8px rgba(0,0,0,.1);margin:0 auto 20px;display:flex;align-items:center;justify-content:center;text-align:center;color:#666;font-size:13px;text-transform:uppercase}
.doc-page .en-name{font-size:2.2em;font-weight:700;color:#1a252f;text-transform:uppercase;margin-bottom:5px;line-height:1.1;letter-spacing:1px}
.doc-page .en-profession{font-size:1.1em;font-weight:500;color:#0d6efd;text-transform:uppercase;margin-bottom:25px;letter-spacing:1px}
.doc-page .en-title{font-size:1.1em;font-weight:700;color:#2c3e50;text-transform:uppercase;border-bottom:2px solid #2c3e50;padding-bottom:5px;margin-top:25px;margin-bottom:15px}
.doc-page .en-sidebar .en-title{border-bottom:2px solid #bdc3c7}
.doc-page .en-contact-item{margin-bottom:12px;display:flex;align-items:flex-start;gap:10px;font-size:.95em}
.doc-page .en-contact-item i{color:#0d6efd;margin-top:4px;width:16px;text-align:center}
.doc-page .en-info-table{width:100%;font-size:.95em}
.doc-page .en-info-table td{padding:4px 0;vertical-align:top}
.doc-page .en-info-table td:first-child{font-weight:600;width:45%;color:#34495e}
.doc-page .en-exp-item{margin-bottom:15px}
.doc-page .en-exp-header{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:3px}
.doc-page .en-exp-title{font-weight:700;font-size:1.1em;color:#2c3e50}
.doc-page .en-exp-date{font-size:.9em;font-weight:600;color:#7f8c8d;background:#eef2f5;padding:2px 8px;border-radius:4px}
.doc-page .en-exp-company{font-weight:600;color:#0d6efd;font-size:.95em;margin-bottom:5px}
.doc-page .en-edu-table{width:100%;border-collapse:collapse;font-size:.9em;margin-top:10px}
.doc-page .en-edu-table th{background:#f8f9fa;border:1px solid #dee2e6;padding:8px;color:#2c3e50;font-weight:600;text-align:left}
.doc-page .en-edu-table td{border:1px solid #dee2e6;padding:8px;color:#444}
.doc-page .bn-cv{padding:40px 50px;position:relative}
.doc-page .bn-header{text-align:center;margin-bottom:30px;position:relative;border-bottom:2px solid #2c3e50;padding-bottom:15px}
.doc-page .bn-header h2{font-weight:bold;margin:0;font-size:26px;color:#1a252f;text-decoration:underline;text-underline-offset:5px}
.doc-page .bn-photo-box{position:absolute;top:-10px;right:0;width:40mm;height:50mm;border:1px solid #999;display:flex;align-items:center;justify-content:center;font-size:13px;color:#999}
.doc-page .bn-title{font-size:18px;font-weight:bold;background:#f0f2f5;padding:6px 12px;border-left:4px solid #2c3e50;margin-top:25px;margin-bottom:15px;color:#2c3e50}
.doc-page .bn-info-table{width:100%;font-size:15px}
.doc-page .bn-info-table td{padding:6px 0;border-bottom:1px dashed #e0e0e0;vertical-align:top}
.doc-page .bn-info-table td:first-child{font-weight:600;width:30%}
.doc-page .bn-info-table td:nth-child(2){width:5%;text-align:center}
.doc-page .bn-edu-table{width:100%;border-collapse:collapse;font-size:14.5px;text-align:center}
.doc-page .bn-edu-table th{border:1px solid #2c3e50;padding:6px;background:#f8f9fa;font-weight:bold}
.doc-page .bn-edu-table td{border:1px solid #2c3e50;padding:6px}
.doc-page .bn-footer{margin-top:60px;width:100%}
